module repeating_decimal_converter ( input clk, input rst_n, input start, input [7:0] decimal_int_part, input [31:0] decimal_frac_part, input [3:0] frac_digits, input [3:0] repeat_count, output reg [63:0] numerator, output reg [63:0] denominator, output reg done, output reg error ); reg [3:0] state; reg [63:0] num, den; reg [63:0] temp_gcd; reg [7:0] counter; reg [31:0] pow10_K, pow10_N; reg [31:0] A, B; reg [31:0] term1; reg [63:0] numerator_val, denominator_val; reg [63:0] original_num, original_den; reg [63:0] final_num, final_den; initial begin state <=4'd0; error <=1'b0; done <=1'b0; numerator <=64'd0; denominator <=64'd0; num <=64'd0; den <=64'd0; temp_gcd <=64'd0; counter <=8'd0; pow10_K <=16'd0; pow10_N <=16'd0; A <=16'd0; B <=16'd0; term1 <=16'd0; numerator_val <=64'd0; denominator_val <=64'd0; original_num <=64'd0; original_den <=64'd0; final_num <=64'd0; final_den <=64'd0; end always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <=4'd0; error <=1'b0; done <=1'b0; numerator <=64'd0; denominator <=64'd0; num <=64'd0; den <=64'd0; temp_gcd <=64'd0; counter <=8'd0; pow10_K <=16'd0; pow10_N <=16'd0; A <=16'd0; B <=16'd0; term1 <=16'd0; numerator_val <=64'd0; denominator_val <=64'd0; original_num <=64'd0; original_den <=64'd0; final_num <=64'd0; final_den <=64'd0; end else begin case(state) 4'd0: begin if (start) state <=4'd1; end 4'd1: begin if (repeat_count > frac_digits) begin error <=1'b1; done <=1'b1; state <=4'd5; numerator <=64'd0; denominator <=64'd0; end else begin case(repeat_count) 1: pow10_K <=10; 2: pow10_K <=100; 3: pow10_K <=1000; 4: pow10_K <=10000; 5: pow10_K <=100000; 6: pow10_K <=1000000; 7: pow10_K <=10000000; 8: pow10_K <=100000000; default: pow10_K <=10; endcase wire [3:0] N_w = frac_digits - repeat_count; case(N_w) 0: pow10_N <=1; 1: pow10_N <=10; 2: pow10_N <=100; 3: pow10_N <=1000; 4: pow10_N <=10000; 5: pow10_N <=100000; 6: pow10_N <=1000000; 7: pow10_N <=10000000; default: pow10_N <=1; endcase A <= decimal_frac_part / pow10_K; B <= decimal_frac_part % pow10_K; term1 <= pow10_K -1; numerator_val <= decimal_int_part * term1 * pow10_N + A * term1 + B; denominator_val <= term1 * pow10_N; original_num <= numerator_val; original_den <= denominator_val; state <=4'd3; num <= original_num; den <= original_den; error <=1'b0; done <=1'b0; end end 4'd3: begin if (den == 64'd0) state <=4'd4; else begin temp_gcd <= den; den <= num % den; num <= temp_gcd; end end 4'd4: begin final_num <= original_num / num; final_den <= original_den / num; state <=4'd5; numerator <= final_num; denominator <= final_den; end end 4'd5: begin numerator <= final_num; denominator <= final_den; done <=1'b1; error <=1'b0; end endcase end end endmodule